CREATE TABLE provider_connections (id TEXT PRIMARY KEY,app_id TEXT NOT NULL,adapter_id TEXT NOT NULL,name TEXT NOT NULL,state TEXT NOT NULL,account_id TEXT NOT NULL,scopes_json TEXT NOT NULL,ownership_json TEXT NOT NULL,credential_ref TEXT,consent_scopes_json TEXT NOT NULL DEFAULT '[]',control_epoch INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,last_checked_at TEXT,last_sync_at TEXT,revoked_at TEXT,remote_revocation_state TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE connection_credentials (connection_id TEXT PRIMARY KEY REFERENCES provider_connections(id),sealed_json TEXT NOT NULL,expires_at TEXT,version INTEGER NOT NULL DEFAULT 1,refresh_owner TEXT,refresh_expires_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE connection_oauth_states (id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES provider_connections(id),actor_id TEXT NOT NULL,session_id TEXT NOT NULL,provider TEXT NOT NULL,state_hash TEXT NOT NULL UNIQUE,verifier_sealed TEXT NOT NULL,redirect_uri TEXT NOT NULL,return_to TEXT NOT NULL,expires_at TEXT NOT NULL,consumed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE connection_webhooks (id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES provider_connections(id),provider_event_id TEXT NOT NULL,body_hash TEXT NOT NULL,received_at TEXT NOT NULL,UNIQUE(connection_id,provider_event_id));
CREATE TABLE connection_mailbox_checkpoints (connection_id TEXT PRIMARY KEY REFERENCES provider_connections(id),scope_hash TEXT NOT NULL,page_token TEXT,observed_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
